window.AUTH=window.AUTH||{};window.AUTH["22-1238"]={"d":"22-1238","id":"2023/22-1238","n":"Office of the United States Trustee v. John Q. Hammons Fall 2006, LLC","briefs":[{"k":"petitioner","label":"Brief of petitioner","date":"2023-11-09","url":"https://www.supremecourt.gov/DocketPDF/22/22-1238/289311/20231109202839032_22-1238%20John%20Q%20Hammons%20merits.pdf","side":"pet","n":55},{"k":"respondent","label":"Brief of respondents John Q. Hammons Fall 2006, LLC, et al.","date":"2023-12-11","url":"https://www.supremecourt.gov/DocketPDF/22/22-1238/293011/20231211155022326_22-1238%20bs.pdf","side":"res","n":34},{"k":"reply","label":"Reply of petitioner Office of the United States Trustee","date":"2023-12-28","url":"https://www.supremecourt.gov/DocketPDF/22/22-1238/294442/20231228121312353_22-1238%20John%20Q%20Hammons%20reply%20final.pdf","side":"pet","n":36}],"opinion":"https://www.supremecourt.gov/opinions/23pdf/602us1r38_mlho.pdf","tr":true,"items":[{"t":"case","label":"American Trucking Ass’ns v. Smith","cite":"496 U.S. 167","y":1990,"id":"1988/88-325","sc":1,"by":{"0":"20"},"q":[{"src":"brief","b":0,"text":"distinguish[ed] the question of retroactivity * * * from the distinct remedial question.","cite":"496 U.S. 167, 178"}]},{"t":"case","label":"Ayotte v. Planned Parenthood","cite":"546 U.S. 320","y":2006,"id":"2005/04-1144","sc":1,"by":{"0":"14, 22, 45","1":"14, 33"},"q":[{"src":"brief","b":0,"text":"[T]he touchstone for any decision about remedy is legislative intent.","cite":"546 U.S. 320, 330"},{"src":"brief","b":0,"text":"the touchstone for any decision about remedy is legislative intent.","cite":"546 U.S. at 330"},{"src":"opinion","who":"Opinion of the Court (Justice Jackson)","text":"[T]he touchstone for any decision about remedy is legislative intent.","cite":"546 U. S., at 330"}]},{"t":"case","label":"Barr v. American Ass’n of Political Consultants","cite":"140 S. Ct. 2335","y":2020,"id":"2019/19-631","sc":1,"by":{"0":"11, 15, 23, 25, 28, 32, 38, 42","1":"19, 20","2":"11, 14, 22"}},{"t":"case","label":"Bob Jones Univ. v. Simon","cite":"416 U.S. 725","y":1974,"id":"1973/72-1470","sc":1,"by":{"0":"30"}},{"t":"case","label":"Califano v. Westcott","cite":"443 U.S. 76","y":1979,"id":"1978/78-437","sc":1,"by":{"0":"26","2":"20"},"q":[{"src":"opinion","who":"Justice Gorsuch, dissenting","text":"regularly . . . affrmed District Court judgments ordering that welfare benefts be paid to members of an unconstitutionally excluded class,","cite":"443 U. S. 76, 90"}]},{"t":"case","label":"CIC Servs., LLC v. IRS","cite":"141 S. Ct. 1582","y":2021,"id":"2020/19-930","sc":1,"by":{"0":"30"}},{"t":"case","label":"Comptroller of the Treasury v. Wynne","cite":"575 U.S. 542","y":2015,"id":"2014/13-485","sc":1,"by":{"0":"22, 27, 34, 42"},"q":[{"src":"brief","b":0,"text":"not help the [challengers] at all.","cite":"575 U.S. at 569"}]},{"t":"case","label":"Cranberry Growers Coop. v. Layng","cite":"930 F.3d 844","y":2019,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/930/844/","by":{"0":"30"}},{"t":"case","label":"Egbert v. Boule","cite":"596 U.S. 482","y":2022,"id":"2021/21-147","sc":1,"by":{"0":"21"}},{"t":"case","label":"Harlow v. Fitzgerald","cite":"457 U.S. 800","y":1982,"id":"1981/80-945","sc":1,"by":{"0":"21"}},{"t":"case","label":"Harper v. Virginia Dep’t of Taxation","cite":"509 U.S. 86","y":1993,"id":"1992/91-794","sc":1,"by":{"0":"12, 20, 21, 29, 31, 35","1":"10, 11, 13, 14, 18, 22","2":"3-6, 14, 15"},"q":[{"src":"brief","b":0,"text":"sufficient by itself to satisfy the Due Process Clause.","cite":"509 U.S. 86, 101"},{"src":"brief","b":0,"text":"the ‘availability of a predeprivation hearing constitutes a procedural safeguard * * * sufficient by itself to satisfy the Due Process Clause.’","cite":"509 U.S. at 101"},{"src":"brief","b":1,"text":"either award full refunds to those burdened by an unlawful [charge] or issue some other order that ‘create[s] in hindsight a nondiscriminatory scheme.’","cite":"509 U.S. 86, 101"},{"src":"brief","b":2,"text":"[t]he constitutional sufficiency of any remedy thus turns (at least initially) on whether [state] law provides an adequate form of predeprivation process,","cite":"509 U.S. at 101"},{"src":"opinion","who":"Opinion of the Court (Justice Jackson)","text":"`a meaningful opportunity for taxpayers to withhold contested tax assessments and to challenge their validity in a predeprivation hearing,' the `availability of a predeprivation hearing constitute[d] a procedural safeguard . . . suffcient by itself to satisfy the Due Process Clause.'","cite":"509 U. S., at 101"},{"src":"argument","who":"Justice Sotomayor","text":"I do agree that McKesson and Harper say, if you have a pre-deprivation mechanism to protect yourself, the government can level up or down because you should have taken advantage of your ability to protect yourself."},{"src":"argument","who":"Mr. Geyser","text":"So the -- under this Court's cases, now it is true that McKesson and Harper suggested in cases where there was not both a pre-deprivation and a post-deprivation --"},{"src":"argument","who":"Mr. Geyser","text":"And -- and to be very clear, Reich and Newsweek both ended by saying, we'll remand for the court -- for the -- for the -- the state in those cases to provide meaningful backward-looking relief, consistent with the Court's mandate in McKesson and Harper."}]},{"t":"case","label":"Heckler v. Mathews","cite":"465 U.S. 728","y":1984,"id":"1983/82-1050","sc":1,"by":{"0":"26, 38","2":"1, 5, 15"},"q":[{"src":"brief","b":0,"text":"us[ing] its remedial powers to circumvent the intent of the legislature,","cite":"465 U.S. at 739 n.5"},{"src":"brief","b":2,"text":"remed[ying] [it] by an end to pref- erential treatment for others.","cite":"465 U.S. at 740 n.8"},{"src":"opinion","who":"Justice Gorsuch, dissenting","text":"is a mandate of equal treatment,","cite":"465 U. S. 728, 740"}]},{"t":"case","label":"Iowa-Des Moines National Bank v. Bennett","cite":"284 U.S. 239","y":1931,"id":"scdb/1931-016","sc":1,"by":{"0":"31","1":"17, 21, 35, 40"},"q":[{"src":"brief","b":1,"text":"to obtain * * * refund of the excess of [fees] exacted from them.","cite":"284 U.S. at 247"}]},{"t":"case","label":"Iowa National Bank v. Stewart","cite":"232 N.W. 445","y":1930,"court":"Iowa","url":"https://www.courtlistener.com/c/N.W./232/445/","by":{"0":"31, 32"}},{"t":"case","label":"Levin v. Commerce Energy, Inc.","cite":"560 U.S. 413","y":2010,"id":"2009/09-223","sc":1,"by":{"0":"14, 15, 26, 35, 42","1":"35"},"q":[{"src":"brief","b":0,"text":"extension or invalidation of the unequally distributed benefit or burden, or some other measure.","cite":"560 U.S. at 426"},{"src":"brief","b":0,"text":"The issue turns on what the legislature would have willed. ‘The relief the complaining party requests does not circumscribe this inquiry.’","cite":"560 U.S. at 427"},{"src":"opinion","who":"Opinion of the Court (Justice Jackson)","text":"How equality is accomplished—by extension or invalidation of the unequally distributed beneft or burden, or some other measure—is a matter on which the Constitution is silent.","cite":"560 U. S., at 426"},{"src":"opinion","who":"Opinion of the Court (Justice Jackson)","text":"within the bounds of [our] institutional competence, . . . implement what the legislature would have willed.","cite":"560 U. S., at 427"},{"src":"argument","who":"Ms. Hansford","text":"So I think the tax cases are classic money cases, and in those cases, Levin -- Levin versus Department of Commerce, McKesson, all those cases lay out that leveling up or leveling down might be appropriate."},{"src":"argument","who":"Ms. Hansford","text":"I think both in Levin versus Department of Commerce and Morales-Santana Footnote 29, the Court said that the -- what the parties asked for does not circumscribe the relief offered and parties never asked for the relief of the withdrawal of the benefit, and the fact that you're allowed to withdraw the benefit shows that you don't need to reward the successful challenger."}]},{"t":"case","label":"McKesson Corp. v. Division of Alcoholic Beverages & Tobacco","cite":"496 U.S. 18","y":1990,"id":"1988/88-192","sc":1,"by":{"0":"22, 25, 26, 29, 30, 31, 35, 38, 42, 44","1":"11, 13, 15, 17, 18, 19, 21","2":"3-5, 9, 12, 22"},"q":[{"src":"brief","b":0,"text":"prospective relief, by itself, exhausts the requirements of federal law.","cite":"496 U.S. at 31"},{"src":"brief","b":0,"text":"the retroactive assessment of a tax increase does not necessarily deny due process to those whose taxes are increased.","cite":"496 U.S. at 40 n.23"},{"src":"brief","b":1,"text":"entitled * * * to a refund of the excess [funds] paid— at least unless the disparity is removed in some other manner.","cite":"496 U.S. at 35"},{"src":"brief","b":1,"text":"benefit[ting] from the rate reductions during the contested [] period, calibrating the retroactive assessment to create in hindsight a nondiscriminatory scheme.","cite":"496 U.S. at 40"},{"src":"brief","b":2,"text":"prospective relief, by itself, exhausts the requirements of federal law.","cite":"496 U.S. at 31"},{"src":"brief","b":2,"text":"The answer is no: If a State places a taxpayer under duress promptly to pay a tax when due and relegates him to a postpayment refund action in which he can challenge the tax’s legality, the Due Process Clause of the Fourteenth Amendment obligates the State to provide meaningful backward-looking relief to rectify any unconstitutional deprivation.","cite":"496 U.S. at 31"},{"src":"argument","who":"Ms. Hansford","text":"So I think the tax cases are classic money cases, and in those cases, Levin -- Levin versus Department of Commerce, McKesson, all those cases lay out that leveling up or leveling down might be appropriate."},{"src":"argument","who":"Justice Thomas","text":"It seems that both -- that McKesson or Reich, those cases go the other -- don't support you, though?"},{"src":"argument","who":"Ms. Hansford","text":"I -- I think that Reich is inapposite here because it's a bait-and-switch case, but I think even in Reich, a case where there was a bait and switch and there was a state statute that promised a refund, but, instead, the state courts tried to say no refund was available, even in that case, the Court left open a determination of relief consistent with McKesson, which could be leveling up or leveling down."}]},{"t":"case","label":"Montana National Bank v. Yellowstone County","cite":"276 U.S. 499","y":1928,"id":"scdb/1927-169","sc":1,"by":{"0":"31"},"q":[{"src":"argument","who":"Mr. Geyser","text":"But those businesses don't have to pay a fee that's been exacted under a constitutionally flawed scheme. I -- I think that's settled under McKesson, Harper, going back to the 1920s, dealing with Montana National Bank and Bennett."}]},{"t":"case","label":"Nashville, Chattanooga & St. Louis Ry. v. Alabama","cite":"128 U.S. 96","y":1888,"id":"scdb/1888-013","sc":1,"by":{"0":"29"}},{"t":"case","label":"Newsweek, Inc. v. Florida Dep’t of Revenue","cite":"522 U.S. 442","y":1998,"id":"1997/97-663","sc":1,"by":{"0":"33, 34","1":"22, 23, 24, 25, 26","2":"5-7"},"q":[{"src":"opinion","who":"Justice Gorsuch, dissenting","text":"declare, only after the disputed [fees] have been paid, that no such remedy exists.","cite":"522 U. S. 442, 444–445"},{"src":"argument","who":"Mr. Geyser","text":"When that question was presented in both Reich and Newsweek, this Court couldn't have been clearer. It said that there has to be an exclusive pre-deprivation remedy."},{"src":"argument","who":"Mr. Geyser","text":"And -- and to be very clear, Reich and Newsweek both ended by saying, we'll remand for the court -- for the -- for the -- the state in those cases to provide meaningful backward-looking relief, consistent with the Court's mandate in McKesson and Harper."},{"src":"argument","who":"Mr. Geyser","text":"I -- I think, if this Court wanted to adopt that theory, it would have to affirmatively overrule Reich and Newsweek. It would really be picking a direct fight that -- in a way that can't be squared with those cases."}]},{"t":"case","label":"Nixon v. Fitzgerald","cite":"457 U.S. 731","y":1982,"id":"1981/79-1738","sc":1,"by":{"0":"21"},"q":[{"src":"brief","b":0,"text":"it is not true that [this Court’s] jurisprudence ordinarily supplies a remedy in civil damages for every legal wrong.","cite":"457 U.S. 731, 754 n.37"}]},{"t":"case","label":"Railway Labor Execs.’ Ass’n v. Gibbons","cite":"455 U.S. 457","y":1982,"id":"1981/80-415","sc":1,"by":{"0":"23","1":"20","2":"10"},"q":[{"src":"brief","b":1,"text":"rectify[ing] its unconstitutional discrimination * * * ‘would plainly cause serious economic and administrative dislocation for the State.’","cite":"455 U.S. 457"}]},{"t":"case","label":"Reich v. Collins","cite":"513 U.S. 106","y":1994,"id":"1994/93-908","sc":1,"by":{"0":"33, 34","1":"10, 12, 22, 23, 24, 25, 26","2":"5-8"},"q":[{"src":"brief","b":1,"text":"entitled to pursue what appear[s] to be a ‘clear and certain’ postdeprivation remedy, regardless of the [government’s] predeprivation remedies.","cite":"513 U.S. at 113"},{"src":"brief","b":1,"text":"predeprivation procedures [is] entirely beside the point (and thus error).","cite":"513 U.S. at 111"},{"src":"brief","b":2,"text":"declar[ing], only after the disputed taxes ha[d] been paid,","cite":"513 U.S. at 108"},{"src":"opinion","who":"Justice Gorsuch, dissenting","text":"declare, only after the disputed [fees] have been paid, that no such remedy exists,","cite":"513 U. S., at 108"},{"src":"argument","who":"Justice Thomas","text":"It seems that both -- that McKesson or Reich, those cases go the other -- don't support you, though?"},{"src":"argument","who":"Justice Thomas","text":"Does Reich help you on the pre-deprivation relief?"},{"src":"argument","who":"Ms. Hansford","text":"I -- I think that Reich is inapposite here because it's a bait-and-switch case, but I think even in Reich, a case where there was a bait and switch and there was a state statute that promised a refund, but, instead, the state courts tried to say no refund was available, even in that case, the Court left open a determination of relief consistent with McKesson, which could be leveling up or leveling down."}]},{"t":"case","label":"Rogers v. Bellei","cite":"401 U.S. 815","y":1971,"id":"1970/24","sc":1,"by":{"0":"28"},"q":[{"src":"brief","b":0,"text":"into something unanticipated and obviously undesired by the Congress.","cite":"401 U.S. 815, 835"}]},{"t":"case","label":"Schweiker v. Chilicky","cite":"487 U.S. 412","y":1988,"id":"1987/86-1781","sc":1,"by":{"0":"20"}},{"t":"case","label":"Seminole Tribe of Florida v. Florida","cite":"517 U.S. 44","y":1996,"id":"1995/94-12","sc":1,"by":{"0":"20"}},{"t":"case","label":"Sessions v. Morales-Santana","cite":"582 U.S. 47","y":2017,"id":"2016/15-1191","sc":1,"by":{"0":"2-5, 7, 9, 10, 16, 18, 21, 28, 35, 38, 41-43","1":"18, 31, 35","2":"7"},"q":[{"src":"brief","b":0,"text":"must adopt the remedial course Congress likely would have chosen ‘had it been apprised of the constitutional infirmity.’","cite":"582 U.S. 47, 77"},{"src":"brief","b":0,"text":"the degree of potential disruption of the statutory scheme that would occur by extension as opposed to abrogation.","cite":"582 U.S. at 75"},{"src":"brief","b":1,"text":"this Court has awarded prospective-only relief in two recent cases,","cite":"582 U.S. 47"},{"src":"brief","b":2,"text":"str[iking] an exception and appl[ying] the general rule equally to all.","cite":"582 U.S. at 75"},{"src":"opinion","who":"Opinion of the Court (Justice Jackson)","text":"`what the legislature would have willed had it been apprised of the constitutional infrmity.'","cite":"582 U. S. 47, 73–74"},{"src":"opinion","who":"Opinion of the Court (Justice Jackson)","text":"courts crafting constitutional remedies consult `the legislature's intent.'","cite":"582 U. S., at 73"}]},{"t":"case","label":"St. Angelo v. Victoria Farms, Inc.","cite":"38 F.3d 1525","y":1994,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/38/1525/","by":{"0":"3, 24","2":"11"}},{"t":"case","label":"USA Sales, Inc. v. Office of the United States Trustee","cite":"76 F.4th 1248","y":2023,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/76/1248/","by":{"0":"24, 33","1":"4, 9, 10, 11, 13, 15, 17, 20, 23, 26, 27, 28, 32"},"q":[{"src":"brief","b":0,"text":"congressional intent is normally the touchstone for determining the remedy for this type of constitutional violation.","cite":"76 F.4th 1248, 1256"},{"src":"brief","b":1,"text":"promising not to take the money again.","cite":"76 F.4th at 1253"},{"src":"brief","b":1,"text":"it was reasonable for [respondents] to pay the quarterly fees * * * and to challenge them only later.","cite":"76 F.4th at 1254"}]},{"t":"case","label":"United States v. Carlton","cite":"512 U.S. 26","y":1994,"id":"1993/92-1941","sc":1,"by":{"0":"42"}},{"t":"case","label":"United States v. Nordic Village, Inc.","cite":"503 U.S. 30","y":1992,"id":"1991/90-1629","sc":1,"by":{"0":"21"}},{"t":"case","label":"United States v. Sperry Corp.","cite":"493 U.S. 52","y":1989,"id":"1989/88-952","sc":1,"by":{"0":"43"}},{"t":"case","label":"United States Trustee Region 21 v. Bast Amron LLP (In re Mosaic Mgmt. Grp., Inc.)","cite":"71 F.4th 1341","y":2023,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/71/1341/","by":{"0":"32, 33, 41"}},{"t":"const","label":"Amendment V","clauses":[["due-process-5","Due Process Clause (Fifth Amendment)"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"0":"23","1":"2, 14, 22, 38"}},{"t":"usc","label":"26 U.S.C. § 7421","url":"https://www.law.cornell.edu/uscode/text/26/7421","subs":["(a)"],"stext":{"head":"§7421. Prohibition of suits to restrain assessment or collection","paras":[[0,"(a) Tax"],[0,"Except as provided in sections 6015(e), 6212(a) and (c), 6213(a), 6232(c), 6330(e)(1), 6331(i), 6672(c), 6694(c), 7426(a) and (b)(1), 7429(b), and 7436, no suit for the purpose of restraining the assessment or collection of any tax shall be maintained in any court by any person, whether or not such person is the person against whom such tax was assessed."],[0,"(b) Liability of transferee or fiduciary"],[0,"No suit shall be maintained in any court for the purpose of restraining the assessment or collection (pursuant to the provisions of chapter 71) of—"],[1,"(1) the amount of the liability, at law or in equity, of a transferee of property of a taxpayer in respect of any internal revenue tax, or"],[1,"(2) the amount of the liability of a fiduciary under section 3713(b) of title 31, United States Code, in respect of any such tax."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/7421?type=usc&year=mostrecent&link-type=html"},"by":{"0":"30","2":"9"},"q":[{"src":"brief","b":0,"text":"suit for the purpose of restraining the assessment or collection of any tax,","cite":"26 U.S.C. 7421(a)"}]},{"t":"law","label":"Pub. L. No. 116-325","url":"https://www.govinfo.gov/link/plaw/116/public/325","by":{"0":"19","1":"2, 3, 6, 7, 8, 12, 15, 16, 21, 33, 34, 38, 41","2":"1, 21"}},{"t":"usc","label":"11 U.S.C. § 101","url":"https://www.law.cornell.edu/uscode/text/11/101","stext":{"head":"§101. Definitions","paras":[[0,"In this title the following definitions shall apply:"],[1,"(1) The term \"accountant\" means accountant authorized under applicable law to practice public accounting, and includes professional accounting association, corporation, or partnership, if so authorized."],[1,"(2) The term \"affiliate\" means—"],[2,"(A) entity that directly or indirectly owns, controls, or holds with power to vote, 20 percent or more of the outstanding voting securities of the debtor, other than an entity that holds such securities—"],[3,"(i) in a fiduciary or agency capacity without sole discretionary power to vote such securities; or"],[3,"(ii) solely to secure a debt, if such entity has not in fact exercised such power to vote;"],[2,"(B) corporation 20 percent or more of whose outstanding voting securities are directly or indirectly owned, controlled, or held with power to vote, by the debtor, or by an entity that directly or indirectly owns, controls, or holds with power to vote, 20 percent or more of the outstanding voting securities of the debtor, other than an entity that holds such securities—"],[3,"(i) in a fiduciary or agency capacity without sole discretionary power to vote such securities; or"],[3,"(ii) solely to secure a debt, if such entity has not in fact exercised such power to vote;"],[2,"(C) person whose business is operated under a lease or operating agreement by a debtor, or person substantially all of whose property is operated under an operating agreement with the debtor; or"],[2,"(D) entity that operates the business or substantially all of the property of the debtor under a lease or operating agreement."],[1,"(3) The term \"assisted person\" means any person whose debts consist primarily of consumer debts and the value of whose nonexempt property is less than $150,000.1"],[1,"(4) The term \"attorney\" means attorney, professional law association, corporation, or partnership, authorized under applicable law to practice law."],[1,"(4A) The term \"bankruptcy assistance\" means any goods or services sold or otherwise provided to an assisted person with the express or implied purpose of providing information, advice, counsel, document preparation, or filing, or attendance at a creditors' meeting or appearing in a case or proceeding on behalf of another or providing legal representation with respect to a case or proceeding under this title."],[1,"(5) The term \"claim\" means—"],[2,"(A) right to payment, whether or not such right is reduced to judgment, liquidated, unliquidated, fixed, contingent, matured, unmatured, disputed, undisputed, legal, equitable, secured, or unsecured; or"],[2,"(B) right to an equitable remedy for breach of performance if such breach gives rise to a right to payment, whether or not such right to an equitable remedy is reduced to judgment, fixed, contingent, matured, unmatured, disputed, undisputed, secured, or unsecured."],[1,"(6) The term \"commodity broker\" means futures commission merchant, foreign futures commission merchant, clearing organization, leverage transaction merchant, or commodity options dealer, as defined in section 761 of this title, with respect to which there is a customer, as defined in section 761 of this title."],[1,"(7) The term \"community claim\" means claim that arose before the commencement of the case concerning the debtor for which property of the kind specified in section 541(a)(2) of this title is liable, whether or not there is any such property at the time of the commencement of the case."],[1,"(7A) The term \"commercial fishing operation\" means—"],[2,"(A) the catching or harvesting of fish, shrimp, lobsters, urchins, seaweed, shellfish, or other aquatic species or products of such species; or"],[2,"(B) for purposes of section 109 and chapter 12, aquaculture activities consisting of raising for market any species or product described in subparagraph (A)."],[1,"(7B) The term \"commercial fishing vessel\" means a vessel used by a family fisherman to carry out a commercial fishing operation."],[1,"(8) The term \"consumer debt\" means debt incurred by an individual primarily for a personal, family, or household purpose."],[1,"(9) The term \"corporation\"—"],[2,"(A) includes—"],[3,"(i) association having a power or privilege that a private corporation, but not an individual or a partnership, possesses;"],[3,"(ii) partnership association organized under a law that makes only the capital subscribed responsible for the debts of such association;"],[3,"(iii) joint-stock company;"],[3,"(iv) unincorporated company or association; or"],[3,"(v) business trust; but"],[2,"(B) does not include limited partnership."],[1,"(10) The term \"creditor\" means—"],[2,"(A) entity that has a claim against the debtor that arose at the time of or before the order for relief concerning the debtor;"],[2,"(B) entity that has a claim against the estate of a kind specified in section 348(d), 502(f), 502(g), 502(h) or 502(i) of this title; or"],[2,"(C) entity that has a community claim."],[1,"(10A) The term \"current monthly income\"—"],[2,"(A) means the average monthly income from all sources that the debtor receives (or in a joint case the debtor and the debtor's spouse receive) without regard to whether such income is taxable income, derived during the 6-month period ending on—"],[3,"(i) the last day of the calendar month immediately preceding the date of the commencement of the case if the debtor files the schedule of current income required by section 521(a)(1)(B)(ii); or"],[3,"(ii) the date on which current income is determined by the court for purposes of this title if the debtor does not file the schedule of current income required by section 521(a)(1)(B)(ii); and"],[2,"(B)(i) includes any amount paid by any entity other than the debtor (or in a joint case the debtor and the debtor's spouse), on a regular basis for the household expenses of the debtor or the debtor's dependents (and in a joint case the debtor's spouse if not otherwise a dependent); and"],[2,"(ii) excludes—"],[3,"(I) benefits received under the Social Security Act (42 U.S.C. 301 et seq.);"],[3,"(II) payments to victims of war crimes or crimes against humanity on account of their status as victims of such crimes;"],[3,"(III) payments to victims of international terrorism or domestic terrorism, as those terms are defined in section 2331 of title 18, on account of their status as victims of such terrorism; and"],[3,"(IV) any monthly compensation, pension, pay, annuity, or allowance paid under title 10, 37, or 38 in connection with a disability, combat-related injury or disability, or death of a member of the uniformed services, except that any retired pay excluded under this subclause shall include retired pay paid under chapter 61 of title 10 only to the extent that such retired pay exceeds the amount of retired pay to which the debtor would otherwise be entitled if retired under any provision of title 10 other than chapter 61 of that title."],[1,"(11) The term \"custodian\" means—"],[2,"(A) receiver or trustee of any of the property of the debtor, appointed in a case or proceeding not under this title;"],[2,"(B) assignee under a general assignment for the benefit of the debtor's creditors; or"],[2,"(C) trustee, receiver, or agent under applicable law, or under a contract, that is appointed or authorized to take charge of property of the debtor for the purpose of enforcing a lien against such property, or for the purpose of general administration of such property for the benefit of the debtor's creditors."],[1,"(12) The term \"debt\" means liability on a claim."],[1,"(12A) The term \"debt relief agency\" means any person who provides any bankruptcy assistance to an assisted person in return for the payment of money or other valuable consideration, or who is a bankruptcy petition preparer under section 110, but does not include—"],[2,"(A) any person who is an officer, director, employee, or agent of a person who provides such assistance or of the bankruptcy petition preparer;"],[2,"(B) a nonprofit organization that is exempt from taxation under section 501(c)(3) of the Internal Revenue Code of 1986;"],[2,"(C) a creditor of such assisted person, to the extent that the creditor is assisting such assisted person to restructure any debt owed by such assisted person to the creditor;"],[2,"(D) a depository institution (as defined in section 3 of the Federal Deposit Insurance Act) or any Federal credit union or State credit union (as those terms are defined in section 101 of the Federal Credit Union Act), or any affiliate or subsidiary of such depository institution or credit union; or"],[2,"(E) an author, publisher, distributor, or seller of works subject to copyright protection under title 17, when acting in such capacity."],[1,"(13) The term \"debtor\" means person or municipality concerning which a case under this title has been commenced."],[1,"(13A) The term \"debtor's principal residence\"—"],[2,"(A) means a residential structure if used as the principal residence by the debtor, including incidental property, without regard to whether that structure is attached to real property; and"],[2,"(B) includes an individual condominium or cooperative unit, a mobile or manufactured home, or trailer if used as the principal residence by the debtor."],[1,"(14) The term \"disinterested person\" means a person that—"],[2,"(A) is not a creditor, an equity security holder, or an insider;"],[2,"(B) is not and was not, within 2 years before the date of the filing of the petition, a director, officer, or employee of the debtor; and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/101?type=usc&year=mostrecent&link-type=html"},"by":{"0":"3, 5, 7, 8, 11, 14, 15, 38, 39","1":"37"}},{"t":"law","label":"Pub. L. No. 115-72","url":"https://www.govinfo.gov/link/plaw/115/public/72","by":{"0":"5","1":"2, 4, 9, 21, 23, 33, 37, 39, 41","2":"1, 2, 8-10, 14, 16, 20-22"}},{"t":"law","label":"Pub. L. No. 99-554","url":"https://www.govinfo.gov/link/statute/100/3090","by":{"0":"2"}},{"t":"law","label":"Pub. L. No. 117-328","url":"https://www.govinfo.gov/link/plaw/117/public/328","by":{"0":"36"}},{"t":"law","label":"Pub. L. No. 106-518","url":"https://www.govinfo.gov/link/plaw/106/public/518","by":{"0":"3"}},{"t":"usc","label":"28 U.S.C. § 581","url":"https://www.law.cornell.edu/uscode/text/28/581","by":{"0":"2"}},{"t":"usc","label":"28 U.S.C. § 589a","url":"https://www.law.cornell.edu/uscode/text/28/589a","subs":["(b)(5)"],"by":{"0":"3,5"}},{"t":"usc","label":"28 U.S.C. § 1930","url":"https://www.law.cornell.edu/uscode/text/28/1930","subs":["(a)","(a)(6)","(a)(6)(2012)","(a)(6)(A)","(a)(6)(B)(2018)","(a)(6)(B)(ii)(II)","(a)(7)(2000)","(a)(7)(2012)","(a)(7)","(b)(6)","(a)(7)(2018)"],"stext":{"head":"§1930. Bankruptcy fees","paras":[[0,"(a) The parties commencing a case under title 11 shall pay to the clerk of the district court or the clerk of the bankruptcy court, if one has been certified pursuant to section 156(b) of this title, the following filing fees:"],[1,"(1) For a case commenced under—"],[2,"(A) chapter 7 of title 11, $245, and"],[2,"(B) chapter 13 of title 11, $235."],[1,"(2) For a case commenced under chapter 9 of title 11, equal to the fee specified in paragraph (3) for filing a case under chapter 11 of title 11. The amount by which the fee payable under this paragraph exceeds $300 shall be deposited in the fund established under section 1931 of this title."],[1,"(3) For a case commenced under chapter 11 of title 11 that does not concern a railroad, as defined in section 101 of title 11, $1,167."],[1,"(4) For a case commenced under chapter 11 of title 11 concerning a railroad, as so defined, $1,000."],[1,"(5) For a case commenced under chapter 12 of title 11, $200."],[1,"(6)(A) Except as provided in subparagraph (B), in addition to the filing fee paid to the clerk, a quarterly fee shall be paid to the United States trustee, for deposit in the Treasury, in each case under chapter 11 of title 11, other than under subchapter V, for each quarter (including any fraction thereof) until the case is converted or dismissed, whichever occurs first. The fee shall be $325 for each quarter in which disbursements total less than $15,000; $650 for each quarter in which disbursements total $15,000 or more but less than $75,000; $975 for each quarter in which disbursements total $75,000 or more but less than $150,000; $1,625 for each quarter in which disbursements total $150,000 or more but less than $225,000; $1,950 for each quarter in which disbursements total $225,000 or more but less than $300,000; $4,875 for each quarter in which disbursements total $300,000 or more but less than $1,000,000; $6,500 for each quarter in which disbursements total $1,000,000 or more but less than $2,000,000; $9,750 for each quarter in which disbursements total $2,000,000 or more but less than $3,000,000; $10,400 for each quarter in which disbursements total $3,000,000 or more but less than $5,000,000; $13,000 for each quarter in which disbursements total $5,000,000 or more but less than $15,000,000; $20,000 for each quarter in which disbursements total $15,000,000 or more but less than $30,000,000; $30,000 for each quarter in which disbursements total more than $30,000,000. The fee shall be payable on the last day of the calendar month following the calendar quarter for which the fee is owed."],[1,"(B)(i) During the 5-year period beginning on January 1, 2021, in addition to the filing fee paid to the clerk, a quarterly fee shall be paid to the United States trustee, for deposit in the Treasury, in each open and reopened case under chapter 11 of title 11, other than under subchapter V, for each quarter (including any fraction thereof) until the case is closed, converted, or dismissed, whichever occurs first."],[1,"(ii) The fee shall be the greater of—"],[2,"(I) 0.4 percent of disbursements or $250 for each quarter in which disbursements total less than $1,000,000; and"],[2,"(II) 0.8 percent of disbursements but not more than $250,000 for each quarter in which disbursements total at least $1,000,000."],[1,"(iii) The fee shall be payable on the last day of the calendar month following the calendar quarter for which the fee is owed."],[1,"(7) In districts that are not part of a United States trustee region as defined in section 581 of this title, the Judicial Conference of the United States shall require the debtor in a case under chapter 11 of title 11 to pay fees equal to those imposed by paragraph (6) of this subsection. Such fees shall be deposited as offsetting receipts to the fund established under section 1931 of this title and shall remain available until expended."],[0,"An individual commencing a voluntary case or a joint case under title 11 may pay such fee in installments. For converting, on request of the debtor, a case under chapter 7, or 13 of title 11, to a case under chapter 11 of title 11, the debtor shall pay to the clerk of the district court or the clerk of the bankruptcy court, if one has been certified pursuant to section 156(b) of this title, a fee of the amount equal to the difference between the fee specified in paragraph (3) and the fee specified in paragraph (1)."],[0,"(b) The Judicial Conference of the United States may prescribe additional fees in cases under title 11 of the same kind as the Judicial Conference prescribes under section 1914(b) of this title."],[0,"(c) Upon the filing of any separate or joint notice of appeal or application for appeal or upon the receipt of any order allowing, or notice of the allowance of, an appeal or a writ of certiorari $5 shall be paid to the clerk of the court, by the appellant or petitioner."],[0,"(d) Whenever any case or proceeding is dismissed in any bankruptcy court for want of jurisdiction, such court may order the payment of just costs."],[0,"(e) The clerk of the court may collect only the fees prescribed under this section."],[0,"(f)(1) Under the procedures prescribed by the Judicial Conference of the United States, the district court or the bankruptcy court may waive the filing fee in a case under chapter 7 of title 11 for an individual if the court determines that such individual has income less than 150 percent of the income official poverty line (as defined by the Office of Management and Budget, and revised annually in accordance with section 673(2) of the Omnibus Budget Reconciliation Act of 1981) applicable to a family of the size involved and is unable to pay that fee in installments. For purposes of this paragraph, the term \"filing fee\" means the filing fee required by subsection (a), or any other fee prescribed by the Judicial Conference under subsections (b) and (c) that is payable to the clerk upon the commencement of a case under chapter 7."],[0,"(2) The district court or the bankruptcy court may waive for such debtors other fees prescribed under subsections (b) and (c)."],[0,"(3) This subsection does not restrict the district court or the bankruptcy court from waiving, in accordance with Judicial Conference policy, fees prescribed under this section for other debtors and creditors."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1930?type=usc&year=mostrecent&link-type=html"},"by":{"0":"3, 5, 16, 25, 17, 3, 5, 17, 7, 17, 4, 16, 43, 6, 44","1":"3, 27, 33, 34, 3, 3","2":"22"},"q":[{"src":"brief","b":0,"text":"quarterly fee shall be paid to the United States trustee * * * for each quarter (including any fraction thereof ) until the case is converted or dismissed, whichever occurs first.","cite":"28 U.S.C. 1930(a)(6)(A)"},{"src":"brief","b":0,"text":"Judicial Conference of the United States shall require the debtor in a case under chapter 11 * * * to pay fees equal to those imposed by paragraph (6) of this subsection.","cite":"28 U.S.C. 1930(a)(7)"}]},{"t":"usc","label":"28 U.S.C. § 1931","url":"https://www.law.cornell.edu/uscode/text/28/1931","subs":["(2000)"],"by":{"0":"4"}},{"t":"usc","label":"28 U.S.C. § 2401","url":"https://www.law.cornell.edu/uscode/text/28/2401","subs":["(a)"],"by":{"0":"36"}},{"t":"usc","label":"31 U.S.C. § 1304","url":"https://www.law.cornell.edu/uscode/text/31/1304","subs":["(a)"],"stext":{"head":"§1304. Judgments, awards, and compromise settlements","paras":[[0,"(a) Necessary amounts are appropriated to pay final judgments, awards, compromise settlements, and interest and costs specified in the judgments or otherwise authorized by law when—"],[1,"(1) payment is not otherwise provided for;"],[1,"(2) payment is certified by the Secretary of the Treasury; and"],[1,"(3) the judgment, award, or settlement is payable—"],[2,"(A) under section 2414, 2517, 2672, or 2677 of title 28;"],[2,"(B) under section 3723 of this title;"],[2,"(C) under a decision of a board of contract appeals; or"],[2,"(D) in excess of an amount payable from the appropriations of an agency for a meritorious claim under section 2733, 2733a, or 2734 of title 10, section 715 of title 32, or section 20113 of title 51."],[0,"(b)(1) Interest may be paid from the appropriation made by this section—"],[1,"(A) on a judgment of a district court, only when the judgment becomes final after review on appeal or petition by the United States Government, and then only from the date of filing of the transcript of the judgment with the Secretary of the Treasury through the day before the date of the mandate of affirmance; or"],[1,"(B) on a judgment of the Court of Appeals for the Federal Circuit or the United States Court of Federal Claims under section 2516(b) of title 28, only from the date of filing of the transcript of the judgment with the Secretary of the Treasury through the day before the date of the mandate of affirmance."],[0,"(2) Interest payable under this subsection in a proceeding reviewed by the Supreme Court is not allowed after the end of the term in which the judgment is affirmed."],[0,"(c)(1) A judgment or compromise settlement against the Government shall be paid under this section and sections 2414, 2517, and 2518 1 of title 28 when the judgment or settlement arises out of an express or implied contract made by—"],[1,"(A) the Army and Air Force Exchange Service;"],[1,"(B) the Navy Exchanges;"],[1,"(C) the Marine Corps Exchanges;"],[1,"(D) the Coast Guard Exchanges; or"],[1,"(E) the Exchange Councils of the National Aeronautics and Space Administration."],[0,"(2) The Exchange making the contract shall reimburse the Government for the amount paid by the Government."],[0,"(d) Beginning not later than the date that is 60 days after the date of enactment of the John D. Dingell, Jr. Conservation, Management, and Recreation Act, and unless the disclosure of such information is otherwise prohibited by law or a court order, the Secretary of the Treasury shall make available to the public on a website, as soon as practicable, but not later than 30 days after the date on which a payment under this section is tendered, the following information with regard to that payment:"],[1,"(1) The name of the specific agency or entity whose actions gave rise to the claim or judgment."],[1,"(2) The name of the plaintiff or claimant."],[1,"(3) The name of counsel for the plaintiff or claimant."],[1,"(4) The amount paid representing principal liability, and any amounts paid representing any ancillary liability, including attorney fees, costs, and interest."],[1,"(5) A brief description of the facts that gave rise to the claim."],[1,"(6) The name of the agency that submitted the claim."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/31/1304?type=usc&year=mostrecent&link-type=html"},"by":{"0":"36","2":"20"}},{"t":"case","label":"Atchison, T. & S.F. Ry. Co. v. O’Connor","cite":"223 U.S. 280","y":1912,"id":"scdb/1911-148","sc":1,"by":{"1":"26, 28","2":"9, 10"},"q":[{"src":"brief","b":2,"text":"an action at law to recover back what he has paid.","cite":"223 U.S. 280, 285"}]},{"t":"case","label":"Bowen v. Georgetown Univ. Hosp.","cite":"488 U.S. 204","y":1988,"id":"1988/87-1097","sc":1,"by":{"1":"30, 35"},"q":[{"src":"argument","who":"Mr. Geyser","text":"When -- when even the Court in the Bowen case asked, does an agency have the general authority just as a background matter to apply statutes retroactively when a regulation is struck down for technical problems, they're basically trying to say, look, we goofed."}]},{"t":"case","label":"Carpenter v. Shaw","cite":"280 U.S. 363","y":1930,"id":"scdb/1929-130","sc":1,"by":{"1":"12"},"q":[{"src":"brief","b":1,"text":"itself in contravention of [due process].","cite":"280 U.S. 363, 369"}]},{"t":"case","label":"Czyzewski v. Jevic Holding Corp.","cite":"137 S. Ct. 973","y":2017,"id":"2016/15-649","sc":1,"by":{"1":"37"}},{"t":"case","label":"INS v. Pangilinan","cite":"486 U.S. 875","y":1988,"id":"1987/86-1992","sc":1,"by":{"1":"19"}},{"t":"case","label":"Landgraf v. USI Film Prods.","cite":"511 U.S. 244","y":1994,"id":"1993/92-757","sc":1,"by":{"1":"30, 32, 35, 36"},"q":[{"src":"brief","b":1,"text":"[a] legislator who supported a prospective statute might reasonably oppose retroactive application of the same statute.","cite":"511 U.S. at 286"}]},{"t":"case","label":"Printz v. United States","cite":"521 U.S. 898","y":1997,"id":"1996/95-1478","sc":1,"by":{"1":"30"}},{"t":"case","label":"Siegel v. Fitzgerald","cite":"596 U.S. 464","y":2022,"id":"2021/21-441","sc":1,"by":{"1":"20","2":"11, 12"},"q":[{"src":"brief","b":1,"text":"burdening only one set of debtors with a more onerous funding mechanism.","cite":"596 U.S. at 476, 480"},{"src":"opinion","who":"Justice Gorsuch, dissenting","text":"funded by the Judiciary's general budget.","cite":"596 U. S., at 469"},{"src":"argument","who":"Ms. Hansford","text":"Chief Justice, and may it please the Court: This case presents the question that this Court left open in Siegel, what the appropriate remedy is for the uniformity violation that resulted when debtors in a small sliver of cases, four dozen cases, in the two states that use bankruptcy administrators did not pay the increased quarterly fees mandated by Congress in the U.S."},{"src":"argument","who":"Ms. Hansford","text":"It responded to the body of lower court cases before they even reached this Court, before the Siegel decision. If these suits had been brought on day one, Congress could have fixed it on day one."}]},{"t":"case","label":"Ward v. Board of Cty. Comm’rs of Love Cty.","cite":"253 U.S. 17","y":1920,"id":"scdb/1919-039","sc":1,"by":{"1":"10, 21","2":"10, 12"},"q":[{"src":"brief","b":1,"text":"‘if a [government] obtains the money or property of others without authority, the law, independent of any statute, will compel restitution or compensation.’","cite":"253 U.S. 17, 24"},{"src":"brief","b":1,"text":"To say that the [government] could collect these unlawful [amounts] by coercive means and not incur any obligation to pay them back is nothing short of saying that it could take or appropriate the property * * * arbitrarily and without due process of law.","cite":"253 U.S. at 24"}]},{"t":"case","label":"West Virginia v. EPA","cite":"142 S. Ct. 2587","y":2022,"id":"2021/20-1530","sc":1,"by":{"1":"30, 36"}},{"t":"usc","label":"11 U.S.C. § 350","url":"https://www.law.cornell.edu/uscode/text/11/350","subs":["(b)"],"by":{"1":"37"}},{"t":"usc","label":"11 U.S.C. § 1112","url":"https://www.law.cornell.edu/uscode/text/11/1112","subs":["(b)(4)(K)","(b)(1)","(b)","(b)(2)(B)"],"stext":{"head":"§1112. Conversion or dismissal","paras":[[0,"(a) The debtor may convert a case under this chapter to a case under chapter 7 of this title unless—"],[1,"(1) the debtor is not a debtor in possession;"],[1,"(2) the case originally was commenced as an involuntary case under this chapter; or"],[1,"(3) the case was converted to a case under this chapter other than on the debtor's request."],[0,"(b)(1) Except as provided in paragraph (2) and subsection (c), on request of a party in interest, and after notice and a hearing, the court shall convert a case under this chapter to a case under chapter 7 or dismiss a case under this chapter, whichever is in the best interests of creditors and the estate, for cause unless the court determines that the appointment under section 1104(a) of a trustee or an examiner is in the best interests of creditors and the estate."],[0,"(2) The court may not convert a case under this chapter to a case under chapter 7 or dismiss a case under this chapter if the court finds and specifically identifies unusual circumstances establishing that converting or dismissing the case is not in the best interests of creditors and the estate, and the debtor or any other party in interest establishes that—"],[1,"(A) there is a reasonable likelihood that a plan will be confirmed within the timeframes established in sections 1121(e) and 1129(e) of this title, or if such sections do not apply, within a reasonable period of time; and"],[1,"(B) the grounds for converting or dismissing the case include an act or omission of the debtor other than under paragraph (4)(A)—"],[2,"(i) for which there exists a reasonable justification for the act or omission; and"],[2,"(ii) that will be cured within a reasonable period of time fixed by the court."],[0,"(3) The court shall commence the hearing on a motion under this subsection not later than 30 days after filing of the motion, and shall decide the motion not later than 15 days after commencement of such hearing, unless the movant expressly consents to a continuance for a specific period of time or compelling circumstances prevent the court from meeting the time limits established by this paragraph."],[0,"(4) For purposes of this subsection, the term \"cause\" includes—"],[1,"(A) substantial or continuing loss to or diminution of the estate and the absence of a reasonable likelihood of rehabilitation;"],[1,"(B) gross mismanagement of the estate;"],[1,"(C) failure to maintain appropriate insurance that poses a risk to the estate or to the public;"],[1,"(D) unauthorized use of cash collateral substantially harmful to 1 or more creditors;"],[1,"(E) failure to comply with an order of the court;"],[1,"(F) unexcused failure to satisfy timely any filing or reporting requirement established by this title or by any rule applicable to a case under this chapter;"],[1,"(G) failure to attend the meeting of creditors convened under section 341(a) or an examination ordered under rule 2004 of the Federal Rules of Bankruptcy Procedure without good cause shown by the debtor;"],[1,"(H) failure timely to provide information or attend meetings reasonably requested by the United States trustee (or the bankruptcy administrator, if any);"],[1,"(I) failure timely to pay taxes owed after the date of the order for relief or to file tax returns due after the date of the order for relief;"],[1,"(J) failure to file a disclosure statement, or to file or confirm a plan, within the time fixed by this title or by order of the court;"],[1,"(K) failure to pay any fees or charges required under chapter 123 of title 28;"],[1,"(L) revocation of an order of confirmation under section 1144;"],[1,"(M) inability to effectuate substantial consummation of a confirmed plan;"],[1,"(N) material default by the debtor with respect to a confirmed plan;"],[1,"(O) termination of a confirmed plan by reason of the occurrence of a condition specified in the plan; and"],[1,"(P) failure of the debtor to pay any domestic support obligation that first becomes payable after the date of the filing of the petition."],[0,"(c) The court may not convert a case under this chapter to a case under chapter 7 of this title if the debtor is a farmer or a corporation that is not a moneyed, business, or commercial corporation, unless the debtor requests such conversion."],[0,"(d) The court may convert a case under this chapter to a case under chapter 12 or 13 of this title only if—"],[1,"(1) the debtor requests such conversion;"],[1,"(2) the debtor has not been discharged under section 1141(d) of this title; and"],[1,"(3) if the debtor requests conversion to chapter 12 of this title, such conversion is equitable."],[0,"(e) Except as provided in subsections (c) and (f), the court, on request of the United States trustee, may convert a case under this chapter to a case under chapter 7 of this title or may dismiss a case under this chapter, whichever is in the best interest of creditors and the estate if the debtor in a voluntary case fails to file, within fifteen days after the filing of the petition commencing such case or such additional time as the court may allow, the information required by paragraph (1) of section 521(a), including a list containing the names and addresses of the holders of the twenty largest unsecured claims (or of all unsecured claims if there are fewer than twenty unsecured claims), and the approximate dollar amounts of each of such claims."],[0,"(f) Notwithstanding any other provision of this section, a case may not be converted to a case under another chapter of this title unless the debtor may be a debtor under such chapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/1112?type=usc&year=mostrecent&link-type=html"},"by":{"1":"26, 26","2":"10, 10, 10"}},{"t":"usc","label":"11 U.S.C. § 1127","url":"https://www.law.cornell.edu/uscode/text/11/1127","by":{"1":"37"}},{"t":"usc","label":"11 U.S.C. § 1129","url":"https://www.law.cornell.edu/uscode/text/11/1129","subs":["(a)(12)"],"stext":{"head":"§1129. Confirmation of plan","paras":[[0,"(a) The court shall confirm a plan only if all of the following requirements are met:"],[1,"(1) The plan complies with the applicable provisions of this title."],[1,"(2) The proponent of the plan complies with the applicable provisions of this title."],[1,"(3) The plan has been proposed in good faith and not by any means forbidden by law."],[1,"(4) Any payment made or to be made by the proponent, by the debtor, or by a person issuing securities or acquiring property under the plan, for services or for costs and expenses in or in connection with the case, or in connection with the plan and incident to the case, has been approved by, or is subject to the approval of, the court as reasonable."],[1,"(5)(A)(i) The proponent of the plan has disclosed the identity and affiliations of any individual proposed to serve, after confirmation of the plan, as a director, officer, or voting trustee of the debtor, an affiliate of the debtor participating in a joint plan with the debtor, or a successor to the debtor under the plan; and"],[1,"(ii) the appointment to, or continuance in, such office of such individual, is consistent with the interests of creditors and equity security holders and with public policy; and"],[1,"(B) the proponent of the plan has disclosed the identity of any insider that will be employed or retained by the reorganized debtor, and the nature of any compensation for such insider."],[1,"(6) Any governmental regulatory commission with jurisdiction, after confirmation of the plan, over the rates of the debtor has approved any rate change provided for in the plan, or such rate change is expressly conditioned on such approval."],[1,"(7) With respect to each impaired class of claims or interests—"],[2,"(A) each holder of a claim or interest of such class—"],[3,"(i) has accepted the plan; or"],[3,"(ii) will receive or retain under the plan on account of such claim or interest property of a value, as of the effective date of the plan, that is not less than the amount that such holder would so receive or retain if the debtor were liquidated under chapter 7 of this title on such date; or"],[2,"(B) if section 1111(b)(2) of this title applies to the claims of such class, each holder of a claim of such class will receive or retain under the plan on account of such claim property of a value, as of the effective date of the plan, that is not less than the value of such holder's interest in the estate's interest in the property that secures such claims."],[1,"(8) With respect to each class of claims or interests—"],[2,"(A) such class has accepted the plan; or"],[2,"(B) such class is not impaired under the plan."],[1,"(9) Except to the extent that the holder of a particular claim has agreed to a different treatment of such claim, the plan provides that—"],[2,"(A) with respect to a claim of a kind specified in section 507(a)(2) or 507(a)(3) of this title, on the effective date of the plan, the holder of such claim will receive on account of such claim cash equal to the allowed amount of such claim;"],[2,"(B) with respect to a class of claims of a kind specified in section 507(a)(1), 507(a)(4), 507(a)(5), 507(a)(6), or 507(a)(7) of this title, each holder of a claim of such class will receive—"],[3,"(i) if such class has accepted the plan, deferred cash payments of a value, as of the effective date of the plan, equal to the allowed amount of such claim; or"],[3,"(ii) if such class has not accepted the plan, cash on the effective date of the plan equal to the allowed amount of such claim;"],[2,"(C) with respect to a claim of a kind specified in section 507(a)(8) of this title, the holder of such claim will receive on account of such claim regular installment payments in cash—"],[3,"(i) of a total value, as of the effective date of the plan, equal to the allowed amount of such claim;"],[3,"(ii) over a period ending not later than 5 years after the date of the order for relief under section 301, 302, or 303; and"],[3,"(iii) in a manner not less favorable than the most favored nonpriority unsecured claim provided for by the plan (other than cash payments made to a class of creditors under section 1122(b)); and"],[2,"(D) with respect to a secured claim which would otherwise meet the description of an unsecured claim of a governmental unit under section 507(a)(8), but for the secured status of that claim, the holder of that claim will receive on account of that claim, cash payments, in the same manner and over the same period, as prescribed in subparagraph (C)."],[1,"(10) If a class of claims is impaired under the plan, at least one class of claims that is impaired under the plan has accepted the plan, determined without including any acceptance of the plan by any insider."],[1,"(11) Confirmation of the plan is not likely to be followed by the liquidation, or the need for further financial reorganization, of the debtor or any successor to the debtor under the plan, unless such liquidation or reorganization is proposed in the plan."],[1,"(12) All fees payable under section 1930 of title 28, as determined by the court at the hearing on confirmation of the plan, have been paid or the plan provides for the payment of all such fees on the effective date of the plan."],[1,"(13) The plan provides for the continuation after its effective date of payment of all retiree benefits, as that term is defined in section 1114 of this title, at the level established pursuant to subsection (e)(1)(B) or (g) of section 1114 of this title, at any time prior to confirmation of the plan, for the duration of the period the debtor has obligated itself to provide such benefits."],[1,"(14) If the debtor is required by a judicial or administrative order, or by statute, to pay a domestic support obligation, the debtor has paid all amounts payable under such order or such statute for such obligation that first become payable after the date of the filing of the petition."],[1,"(15) In a case in which the debtor is an individual and in which the holder of an allowed unsecured claim objects to the confirmation of the plan—"],[2,"(A) the value, as of the effective date of the plan, of the property to be distributed under the plan on account of such claim is not less than the amount of such claim; or"],[2,"(B) the value of the property to be distributed under the plan is not less than the projected disposable income of the debtor (as defined in section 1325(b)(2)) to be received during the 5-year period beginning on the date that the first payment is due under the plan, or during the period for which the plan provides payments, whichever is longer."],[1,"(16) All transfers of property under the plan shall be made in accordance with any applicable provisions of nonbankruptcy law that govern the transfer of property by a corporation or trust that is not a moneyed, business, or commercial corporation or trust."],[0,"(b)(1) Notwithstanding section 510(a) of this title, if all of the applicable requirements of subsection (a) of this section other than paragraph (8) are met with respect to a plan, the court, on request of the proponent of the plan, shall confirm the plan notwithstanding the requirements of such paragraph if the plan does not discriminate unfairly, and is fair and equitable, with respect to each class of claims or interests that is impaired under, and has not accepted, the plan."],[0,"(2) For the purpose of this subsection, the condition that a plan be fair and equitable with respect to a class includes the following requirements:"],[1,"(A) With respect to a class of secured claims, the plan provides—"],[2,"(i)(I) that the holders of such claims retain the liens securing such claims, whether the property subject to such liens is retained by the debtor or transferred to another entity, to the extent of the allowed amount of such claims; and"],[2,"(II) that each holder of a claim of such class receive on account of such claim deferred cash payments totaling at least the allowed amount of such claim, of a value, as of the effective date of the plan, of at least the value of such holder's interest in the estate's interest in such property;"],[2,"(ii) for the sale, subject to section 363(k) of this title, of any property that is subject to the liens securing such claims, free and clear of such liens, with such liens to attach to the proceeds of such sale, and the treatment of such liens on proceeds under clause (i) or (iii) of this subparagraph; or"],[2,"(iii) for the realization by such holders of the indubitable equivalent of such claims."],[1,"(B) With respect to a class of unsecured claims—"],[2,"(i) the plan provides that each holder of a claim of such class receive or retain on account of such claim property of a value, as of the effective date of the plan, equal to the allowed amount of such claim; or"],[2,"(ii) the holder of any claim or interest that is junior to the claims of such class will not receive or retain under the plan on account of such junior claim or interest any property, except that in a case in which the debtor is an individual, the debtor may retain property included in the estate under section 1115, subject to the requirements of subsection (a)(14) of this section."],[1,"(C) With respect to a class of interests—"],[2,"(i) the plan provides that each holder of an interest of such class receive or retain on account of such interest property of a value, as of the effective date of the plan, equal to the greatest of the allowed amount of any fixed liquidation preference to which such holder is entitled, any fixed redemption price to which such holder is entitled, or the value of such interest; or"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/1129?type=usc&year=mostrecent&link-type=html"},"by":{"1":"23, 27","2":"17"}},{"t":"usc","label":"11 U.S.C. § 1141","url":"https://www.law.cornell.edu/uscode/text/11/1141","by":{"1":"37"},"q":[{"src":"argument","who":"Mr. Geyser","text":"They have to go into the bankruptcy case; they have to upset a final and non-appealable confirmation order. Right away you're violating Section 1141 of the Bankruptcy Code."}]},{"t":"case","label":"Associated Indus. of Missouri v. Lohman","cite":"511 U.S. 641","y":1994,"id":"1993/93-397","sc":1,"by":{"2":"5"},"q":[{"src":"brief","b":2,"text":"is itself sufficient to satisfy constitutional concerns","cite":"511 U.S. 641, 656"}]},{"t":"case","label":"City of Los Angeles v. Manhart","cite":"435 U.S. 702","y":1978,"id":"1977/76-1810","sc":1,"by":{"2":"11"}},{"t":"case","label":"Dynamic Int’l Airways, LLC, In re","cite":"516 U.S. 325","y":1996,"id":"1995/94-1239","sc":1,"by":{"2":"6"}},{"t":"case","label":"Griffin v. County Sch. Bd.","cite":"377 U.S. 218","y":1964,"id":"1963/592","sc":1,"by":{"2":"15"}},{"t":"case","label":"Norwood v. Harrison","cite":"413 U.S. 455","y":1973,"id":"1972/72-77","sc":1,"by":{"2":"15"}},{"t":"case","label":"Trinity Lutheran Church of Columbia, Inc. v. Comer","cite":"582 U.S. 449","y":2017,"id":"2016/15-577","sc":1,"by":{"2":"15"}},{"t":"const","label":"Amendment XIV","clauses":[["due-process-14","Due Process Clause (Fourteenth Amendment)"]],"by":{"2":"6, 8"}},{"t":"usc","label":"5 U.S.C. § 702","url":"https://www.law.cornell.edu/uscode/text/5/702","by":{"2":"7"}},{"t":"usc","label":"28 U.S.C. § 1341","url":"https://www.law.cornell.edu/uscode/text/28/1341","by":{"2":"9"}},{"t":"usc","label":"28 U.S.C. § 2201","url":"https://www.law.cornell.edu/uscode/text/28/2201","subs":["(a)"],"by":{"2":"7, 9"}},{"t":"usc","label":"31 U.S.C. § 3716","url":"https://www.law.cornell.edu/uscode/text/31/3716","by":{"2":"18"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","by":{"2":"7"}},{"t":"reg","label":"28 C.F.R. § 11.12","url":"https://www.ecfr.gov/current/title-28/section-11.12","subs":["(b)"],"by":{"2":"18"}},{"t":"reg","label":"31 C.F.R. § 901.8","url":"https://www.ecfr.gov/current/title-31/section-901.8","by":{"2":"18"}}]};